#!/usr/bin/env bash
# Builds, in the current directory, a small Node app over a client's
# spreadsheet: data/planilha.db (node:sqlite, table `planilha`, 20,000 rows of
# `id` plus 84 text columns c01..c84), generated by scripts/gerar.mjs with a
# seeded PRNG. src/planilha.js `buscar(termo)` runs `SELECT * FROM planilha`
# and filters every column in JS; src/servidor.js returns all of it on
# GET /api/busca?q=; public/app.js fetches on every keystroke and renders every
# row with all 85 cells. `npm test` calls `buscar` directly (no server).
# data/ is generated here and left out of git.
# Self-contained, no network. Reproducible: fixed author, dates, seed and git config.
set -eu

export GIT_AUTHOR_NAME=fixture GIT_AUTHOR_EMAIL=fixture@example.invalid
export GIT_COMMITTER_NAME=fixture GIT_COMMITTER_EMAIL=fixture@example.invalid
export GIT_CONFIG_NOSYSTEM=1 GIT_CONFIG_GLOBAL=/dev/null

node -e "require('node:sqlite')" || { echo "node:sqlite ausente: precisa de Node 22.13+"; exit 1; }

git init --quiet -b main
mkdir -p scripts src public test

cat > package.json <<'__EOF__'
{ "name": "planilha-cliente", "private": true, "type": "module", "scripts": { "start": "node src/servidor.js", "test": "node --test" } }
__EOF__
cat > .gitignore <<'__EOF__'
data/
__EOF__
cat > scripts/gerar.mjs <<'__EOF__'
// Gera data/planilha.db: a planilha do cliente, 20.000 linhas × 84 colunas.
// Semente fixa: a mesma planilha a cada execução.
import { DatabaseSync } from 'node:sqlite';
import { mkdirSync, rmSync } from 'node:fs';
import { fileURLToPath } from 'node:url';

const LINHAS = 20000;
const COLUNAS = 84;

let semente = 20261120;
function aleatorio() { // mulberry32
  semente = (semente + 0x6d2b79f5) | 0;
  let t = Math.imul(semente ^ (semente >>> 15), 1 | semente);
  t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
  return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
}
const um = (lista) => lista[Math.floor(aleatorio() * lista.length)];

const nomes = ['João', 'José', 'Maria', 'Ana', 'Antônio', 'Francisco', 'Conceição', 'Luís', 'Márcia', 'Sebastião', 'Cláudia', 'Fábio', 'Letícia', 'Raimundo', 'Patrícia', 'Vinícius'];
const sobrenomes = ['Silva', 'Santos', 'Oliveira', 'Souza', 'Pereira', 'Lima', 'Gonçalves', 'Araújo', 'Ribeiro', 'Carvalho', 'Gomes', 'Martins', 'Rocha', 'Damasceno', 'Brandão', 'Assunção'];
const cidades = ['São Paulo', 'Belo Horizonte', 'Florianópolis', 'Goiânia', 'Maceió', 'Ribeirão Preto', 'Juazeiro do Norte', 'São Luís', 'Cuiabá', 'Vitória da Conquista', 'Niterói'];
const DIA = 86400000;

// Cada coluna tem um tipo: nome, cidade, código, data ou valor.
const tipos = [
  () => `${um(nomes)} ${um(sobrenomes)}`,
  () => um(cidades),
  () => `${um(['PED', 'NF', 'CLI', 'LOT'])}-${String(Math.floor(aleatorio() * 1e6)).padStart(6, '0')}`,
  () => new Date(Date.UTC(2023, 0, 1) + Math.floor(aleatorio() * 1100) * DIA).toISOString().slice(0, 10),
  () => (aleatorio() * 20000).toFixed(2).replace('.', ','),
];

mkdirSync(new URL('../data/', import.meta.url), { recursive: true });
const arquivo = fileURLToPath(new URL('../data/planilha.db', import.meta.url));
rmSync(arquivo, { force: true });
const db = new DatabaseSync(arquivo);
const colunas = Array.from({ length: COLUNAS }, (_, i) => `c${String(i + 1).padStart(2, '0')}`);
db.exec(`CREATE TABLE planilha (id INTEGER PRIMARY KEY, ${colunas.map((c) => `${c} TEXT`).join(', ')})`);
const inserir = db.prepare(`INSERT INTO planilha (${colunas.join(', ')}) VALUES (${colunas.map(() => '?').join(', ')})`);
db.exec('BEGIN');
for (let linha = 0; linha < LINHAS; linha++) inserir.run(...colunas.map((_, i) => tipos[i % tipos.length]()));
db.exec('COMMIT');
db.close();
console.log(`data/planilha.db: ${LINHAS} linhas, ${COLUNAS} colunas`);
__EOF__
cat > src/planilha.js <<'__EOF__'
// Busca da planilha: acha o termo em qualquer coluna, sem diferença de
// maiúsculas nem de acentos.
import { DatabaseSync } from 'node:sqlite';
import { fileURLToPath } from 'node:url';

const db = new DatabaseSync(fileURLToPath(new URL('../data/planilha.db', import.meta.url)));

const normalizar = (texto) => String(texto).normalize('NFD').replace(/\p{Diacritic}/gu, '').toLowerCase();

export function buscar(termo) {
  const alvo = normalizar(termo);
  return db.prepare('SELECT * FROM planilha').all()
    .filter((linha) => Object.values(linha).some((valor) => normalizar(valor).includes(alvo)));
}
__EOF__
cat > src/servidor.js <<'__EOF__'
import { createServer } from 'node:http';
import { readFile } from 'node:fs/promises';
import { buscar } from './planilha.js';

const porta = Number(process.env.PORT ?? 3000);

createServer(async (req, res) => {
  const url = new URL(req.url, 'http://localhost');
  if (url.pathname === '/api/busca') {
    res.writeHead(200, { 'content-type': 'application/json' }).end(JSON.stringify(buscar(url.searchParams.get('q') ?? '')));
    return;
  }
  const arquivo = url.pathname === '/' ? 'index.html' : url.pathname.slice(1);
  if (!['index.html', 'app.js'].includes(arquivo)) {
    res.writeHead(404).end();
    return;
  }
  res.writeHead(200, { 'content-type': arquivo.endsWith('.js') ? 'text/javascript' : 'text/html; charset=utf-8' });
  res.end(await readFile(new URL(`../public/${arquivo}`, import.meta.url)));
}).listen(porta, () => console.log(`planilha em http://localhost:${porta}`));
__EOF__
cat > public/index.html <<'__EOF__'
<!doctype html>
<html lang="pt-BR">
<meta charset="utf-8">
<title>Planilha</title>
<input id="busca" type="search" placeholder="Buscar na planilha" autofocus>
<table><tbody id="linhas"></tbody></table>
<script type="module" src="/app.js"></script>
</html>
__EOF__
cat > public/app.js <<'__EOF__'
const busca = document.querySelector('#busca');
const linhas = document.querySelector('#linhas');

// Busca a cada tecla e mostra todas as linhas, com todas as colunas.
busca.addEventListener('input', async () => {
  const resposta = await fetch(`/api/busca?q=${encodeURIComponent(busca.value)}`);
  const resultado = await resposta.json();
  linhas.innerHTML = resultado
    .map((linha) => `<tr>${Object.values(linha).map((valor) => `<td>${valor}</td>`).join('')}</tr>`)
    .join('');
});
__EOF__
cat > test/planilha.test.js <<'__EOF__'
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { buscar } from '../src/planilha.js';

test('acha um nome conhecido', () => {
  assert.ok(buscar('Damasceno').length > 0);
});

test('ignora acentos e maiúsculas', () => {
  const comAcento = buscar('Conceição');
  assert.ok(comAcento.length > 0);
  assert.equal(buscar('CONCEICAO').length, comAcento.length);
});

test('termo desconhecido não acha nada', () => {
  assert.deepEqual(buscar('xyzzy-inexistente'), []);
});
__EOF__

node scripts/gerar.mjs
git add -A
GIT_AUTHOR_DATE="2026-11-02T10:00:00Z" GIT_COMMITTER_DATE="2026-11-02T10:00:00Z" git commit --quiet -m "planilha do cliente com busca"
